 {code:'MKT',name:'Marketing & Advertising',tags:'marketing advertising branding media',prospects:['Hotels','Restaurants','Banks','NGOs','Schools','Real estate','Retailers','Manufacturers','Telecom','Professional firms','Events companies'],opps:['Marketing contracts','Advertising contracts','Branding projects','Social media contracts','Event campaigns','Corporate campaigns']},
 {code:'CLN',name:'Cleaning & Facility Management',tags:'cleaning facility hygiene',prospects:['Offices','Hotels','Schools','Hospitals','Shopping malls','Factories','Churches','Government institutions','NGOs','Apartments','Property managers'],opps:['Office cleaning contracts','Hotel contracts','Facility-management contracts','Government tenders','NGO procurement']},
 {code:'SEC',name:'Security',tags:'security guard cctv',prospects:['Banks','Hotels','Schools','Hospitals','Factories','Warehouses','Construction companies','Shopping centres','Offices','NGOs','Residential estates'],opps:['Security tenders','Guarding contracts','CCTV projects','Access-control projects','Facility contracts']},
 {code:'CAT',name:'Catering & Food Services',tags:'catering food restaurant events',prospects:['Corporates','NGOs','Schools','Universities','Hospitals','Hotels','Event companies','Churches','Government agencies'],opps:['Corporate catering','Event catering','Conference catering','NGO workshop catering','School meals','Government events']},
 {code:'PRN',name:'Printing & Branding',tags:'printing branding design signage',prospects:['Schools','NGOs','Corporates','Government agencies','Churches','Hotels','Events companies','Publishers','Ad agencies'],opps:['Annual reports','Brochures','Banners','Books','Stationery','Merchandise','Event materials']},
 {code:'FUR',name:'Office Furniture',tags:'furniture office interior',prospects:['Companies','Schools','Hospitals','Hotels','NGOs','Government institutions','Banks','Offices','Co-working spaces','Property developers'],opps:['Office furnishing','School furniture','Hospital furniture','Hotel furniture','Government procurement','NGO procurement']},
 {code:'ACC',name:'Accounting & Professional Services',tags:'accounting audit tax finance',prospects:['SMEs','NGOs','Schools','Churches','SACCOs','Startups','Companies','Cooperatives','Associations'],opps:['Audit contracts','Accounting contracts','Bookkeeping','Tax consultancy','Payroll','Financial reporting']},
 {code:'LOG',name:'Logistics & Transport',tags:'logistics transport delivery fleet',prospects:['Importers','Exporters','Manufacturers','Retailers','Wholesalers','NGOs','Construction companies','Distributors','E-commerce'],opps:['Delivery contracts','Transport contracts','Fleet contracts','Logistics tenders','Freight and distribution']},
 {code:'AGR',name:'Agriculture & Agribusiness',tags:'agriculture farming agro',prospects:['Farmers','Commercial farms','Cooperatives','NGOs','Government programs','Agro-processors','Distributors','Agri projects'],opps:['Agri procurement','Seed and fertilizer supply','Equipment supply','Agri projects','Government programs','NGO projects']},
